          // test; both operands carry the union type.
          const h = this.unionTruthyHelper(e.type.unionId, e.loc);
          if (h === null) {
            code.unreachable();
            return;
          }
          const t = this.unions.baseRef();
          this.walkExpr(e.left);
          const s = this.acquireScratch(t);
          code.localSet(s);
          code.localGet(s);
          code.call(h);
