        // order) — canonical struct layout never reorders effects.
        const recRef: ValType = { kind: "ref", nullable: true, typeIndex: info.struct };
        const rec = this.acquireScratch(recRef);
        code.structNewDefault(info.struct);
        code.localSet(rec);
