          code.localGet(c);
          code.structGet(exc.caughtT, 1);
          code.call(this.f64ToStrHelper());
          code.else_();
          kindIs(EXC_BOOL);
          this.openIfResult(this.strRef);
          code.localGet(c);
          code.structGet(exc.caughtT, 1);
          code.f64Const(0);
          code.f64Ne();
          this.openIfResult(this.strRef);
          this.pushStrLit("true");
          code.else_();
          this.pushStrLit("false");
          this.close();
          code.else_();
          kindIs(EXC_STR);
