          code.else_();
          code.i32Const(0);
          this.close();
          this.openIfResult(this.strRef);
          code.localGet(c);
          code.structGet(exc.caughtT, 2);
          code.refCast(exc.errT);
          code.call(this.errToStrHelper());
          code.else_();
