      c.i32Const(0);
      c.arrayGetU(this.strType);
      c.i32Const(0x30); // '0'
      c.i32Eq();
      c.ifVoid();
      c.localGet(T);
      c.i32Const(1);
      c.arrayGetU(this.strType);
      c.localTee(C1);
      c.i32Const(0x78); // 'x'
      c.i32Eq();
      c.localGet(C1);
      c.i32Const(0x58); // 'X'
      c.i32Eq();
      c.i32Or();
      c.ifVoid();
      c.localGet(T);
      c.i32Const(2);
      c.localGet(L);
      c.i32Const(16);
