    this.jsIsStrLikeFunc = idx;
    const c = new Code();
    const dynT = this.dyn.dynT();
    const K = 1;
    c.localGet(0);
    c.structGet(dynT, DYN_KIND);
    c.localSet(K);
    c.localGet(K);
    c.i32Const(DK.NUM);
    c.i32Eq();
    c.localGet(K);
    c.i32Const(DK.BOOL);
    c.i32Eq();
    c.i32Or();
    c.localGet(K);
    c.i32Const(DK.UNDEF);
    c.i32Eq();
    c.i32Or();
    c.localGet(K);
